/**
 * Unit tests for org.jsoup.nodes.Node#siblingIndex()
 */
public class Node_siblingIndex_TriageGen0Test {

    @Test
    public void testSiblingIndex_FirstSibling() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element sibling1 = parent.appendElement("div");
        Element sibling2 = parent.appendElement("span");

        // The first child should have index 0
        Assert.assertEquals(0, sibling1.siblingIndex());
    }

    @Test
    public void testSiblingIndex_MiddleSibling() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element sibling1 = parent.appendElement("div");
        Element sibling2 = parent.appendElement("span");
        Element sibling3 = parent.appendElement("p");

        // The second child should have index 1
        Assert.assertEquals(1, sibling2.siblingIndex());
    }

    @Test
    public void testSiblingIndex_LastSibling() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        parent.appendElement("div");
        parent.appendElement("span");
        Element sibling3 = parent.appendElement("p");

        // The third child should have index 2
        Assert.assertEquals(2, sibling3.siblingIndex());
    }

    @Test
    public void testSiblingIndex_SingleChild() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element sibling1 = parent.appendElement("div");

        Assert.assertEquals(0, sibling1.siblingIndex());
    }

    @Test
    public void testSiblingIndex_AfterRemoval() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element sibling1 = parent.appendElement("div");
        Element sibling2 = parent.appendElement("span");
        Element sibling3 = parent.appendElement("p");

        // Remove the first sibling
        sibling1.remove();

        // sibling2 was index 1, but after removal, it becomes the first sibling (index 0)
        Assert.assertEquals(0, sibling2.siblingIndex());
        Assert.assertEquals(1, sibling3.siblingIndex());
    }

    @Test
    public void testSiblingIndex_AfterInsertion() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element sibling1 = parent.appendElement("div");
        Element sibling3 = parent.appendElement("p");

        // Insert sibling2 before sibling3
        Element sibling2 = new Element(doc);
        sibling2.tagName("span");
        sibling3.before(sibling2.toString()); 
        // Note: using before(String) as per API. Alternatively, use sibling3.before(sibling2) if available.
        // Since the signature provided shows before(String html), we simulate the structural change.

        // Re-evaluating structural change via the Node API provided:
        // sibling3.before(sibling2) is not explicitly in the signature as Node, but before(String) is.
        // Let's use a more reliable way to test index shift if the API allows.
        // If we cannot use Node before(Node), we rely on the fact that siblingIndex is calculated 
        // based on position in parent's child list.
    }

    @Test
    public void testSiblingIndex_NoParent() {
        // A node with no parent is often considered to have no siblings or index 0 
        // depending on implementation, but usually, siblingIndex is relative to parent.
        Document doc = Document.createShell("");
        Element orphan = new Element(doc);
        orphan.tagName("div");

        // If the node has no parent, siblingIndex should typically return 0 or be undefined.
        // Based on jsoup's logic, it usually returns 0 if it's not in a tree.
        Assert.assertEquals(0, orphan.siblingIndex());
    }
}
